import os
import hashlib
import hmac
import re
from pathlib import PurePosixPath
import unicodedata

# Secure file storage service
SECRET_KEY = os.environ.get('STORAGE_SECRET')
if not SECRET_KEY:
    raise RuntimeError('STORAGE_SECRET environment variable required')

BASE_DIR = '/var/storage/user_files'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}

def generate_access_token(username, filename):
    """Generate HMAC token for file access authorization."""
    message = f"{username}:{filename}".encode('utf-8')
    return hmac.new(SECRET_KEY.encode('utf-8'), message, hashlib.sha256).hexdigest()

def verify_access_token(username, filename, token):
    """Verify the HMAC access token."""
    expected = generate_access_token(username, filename)
    return hmac.compare_digest(expected, token)

def sanitize_username(username):
    """Validate username format."""
    if not username or not isinstance(username, str):
        return None
    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return None
    return username

def validate_path_component(filename):
    """Check that filename doesn't contain path traversal sequences."""
    # Block obvious traversal patterns
    if '..' in filename:
        return False
    if filename.startswith('/'):
        return False
    if '\\' in filename:
        return False
    # Must have an allowed extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return False
    # No null bytes
    if '\x00' in filename:
        return False
    return True

def normalize_filename(filename):
    """Normalize Unicode in filename to canonical form."""
    # NFC normalization for consistent storage
    normalized = unicodedata.normalize('NFC', filename)
    return normalized

def resolve_file_path(username, filename):
    """Resolve the full file path for a user's file."""
    user_dir = os.path.join(BASE_DIR, username)
    # Validate path component BEFORE normalization
    if not validate_path_component(filename):
        return None
    # Normalize AFTER validation
    safe_filename = normalize_filename(filename)
    full_path = os.path.join(user_dir, safe_filename)
    return full_path

def read_file(username, filename, token):
    """Main entry point: authenticate and read a file."""
    # Validate username
    clean_username = sanitize_username(username)
    if not clean_username:
        return {'error': 'Invalid username', 'status': 403}

    # Verify access token
    if not verify_access_token(clean_username, filename, token):
        return {'error': 'Invalid access token', 'status': 401}

    # Resolve path
    file_path = resolve_file_path(clean_username, filename)
    if not file_path:
        return {'error': 'Invalid filename', 'status': 400}

    # Final safety check: ensure resolved path is under BASE_DIR
    real_base = os.path.realpath(BASE_DIR)
    real_path = os.path.realpath(file_path)
    if not real_path.startswith(real_base + os.sep):
        return {'error': 'Access denied', 'status': 403}

    # Read and return file
    try:
        with open(real_path, 'r') as f:
            content = f.read()
        return {'content': content, 'status': 200}
    except FileNotFoundError:
        return {'error': 'File not found', 'status': 404}
    except PermissionError:
        return {'error': 'Permission denied', 'status': 403}
